from typing import Union, Dict, Any
import pandas as pd

def process_data(data: dict) -> dict:
    result = {}
    for key, value in data.items():
        result[key] = str(value).upper()
    return result

def validate_input(value: str) -> bool:
    return len(value) > 0

class DataHandler:
    def __init__(self, source: str):
        self.source = source
        self.data = {}

    def load(self) -> bool:
        return True

    def transform(
        self,
        data: Union[pd.DataFrame, Dict[str, Any]],
        rules: Dict[str, Any]
    ) -> Union[pd.DataFrame, Dict[str, Any]]:
        """
        Transform the input data according to the provided rules.
        - If `data` is a DataFrame, return a DataFrame.
        - If `data` is a dict, return a dict.
        """
        if isinstance(data, pd.DataFrame):
            # 示例：对 DataFrame 进行规则处理，这里直接返回原 DataFrame
            return data
        else:
            # 示例：对 dict 类型应用 rules 中的 func（如果提供）
            func = rules.get("func")
            if func:
                return {k: func(v) for k, v in data.items()}
            # 若无 func，则保持原样返回
            return data

    def save(self, path: str) -> bool:
        return True

